using System.Text.Json;
using VisionPlugins.MapCalibration;
var matrices=new Dictionary<int,float[]>();int count=0;
foreach(var line in File.ReadLines("analysis/map-calibration/native/module-file-results.jsonl")){using var d=JsonDocument.Parse(line);var r=d.RootElement;if(!r.TryGetProperty("case",out var c)||!r.TryGetProperty("side",out _))continue;int side=r.GetProperty("side").GetInt32(),index=c.GetInt32();var path=$"analysis/map-calibration/native/reader-{index}.xml"+(index==3?".suffix":"");var read=MapCalibrationFiles.Read(path);if(read.Replacement is {} replacement)matrices[side]=replacement;if(read.ErrorCode!=r.GetProperty("code").GetUInt32())throw new Exception($"Error mismatch {index}/{side}");count++;var original=r.GetProperty("matrix").EnumerateArray().Select(v=>v.GetSingle()).ToArray();if(!matrices.TryGetValue(side,out var actual))throw new Exception("Missing matrix");for(int i=0;i<9;i++){if(actual[i]!=original[i])throw new Exception($"Matrix mismatch {index}/{side}/{i}: {actual[i]} vs {original[i]}");count++;}}
var example=File.ReadLines("analysis/map-calibration/native/results.jsonl").Select(s=>JsonDocument.Parse(s)).Single(d=>d.RootElement.GetProperty("case").GetInt32()==4).RootElement.GetProperty("matrix").EnumerateArray().Select(v=>v.GetSingle()).ToArray();var xml=MapCalibrationFiles.FileModeXml(example);if(xml!=File.ReadAllText("analysis/map-calibration/native/module-export.xml"))throw new Exception("Module file bytes differ");count++;foreach(var row in File.ReadLines("analysis/map-calibration/native/module-file-results.jsonl")){using var document=JsonDocument.Parse(row);var native=document.RootElement;if(!native.TryGetProperty("phase",out var phase)||phase.GetString()!="writer-failure")continue;int failure=native.GetProperty("case").GetInt32();string suffix=failure switch{0=>"module-absent-parent/output.xml",1=>"module-wrong.iwcal",2=>"module-upper.XML",3=>"module-suffix.xml.bak",4=>"module-empty.",_=>"directory.xml/no-extension"};var saved=MapCalibrationFiles.SaveFileModeOperation(Path.GetFullPath("analysis/map-calibration/native/"+suffix),example);if(saved.ErrorCode!=native.GetProperty("setCode").GetUInt32())throw new Exception("Save operation error "+failure);if((saved.ErrorCode==0)!=native.GetProperty("pathPersisted").GetBoolean())throw new Exception("Path commit eligibility "+failure);if(failure==0&&saved.Written)throw new Exception("Missing parent unexpectedly written");count+=3;}Console.WriteLine($"PASS {count}: original module read/error/cache matrix and file-mode XML byte comparison");File.WriteAllText("analysis/map-calibration/file-checks.json",JsonSerializer.Serialize(new{checks=count,passed=true,generatedUtc=DateTime.UtcNow}));


